import { colors, Theme, useTheme } from '@/theme'
import { MenuComponentRef, MenuView, MenuAction } from '@react-native-menu/menu'
import { ChevronRight } from 'lucide-react-native'
import { Text, View } from 'react-native'
import { useRef } from 'react'
import { MenuActionWithCustomIcon } from './Bottom'
import { defineStyles } from '@/utils/defineStyles'

type MappedColorsType = {
	backgroundColor?: string
	borderColor: string
}

type ModeDropdownProps = {
	mode: MenuActionWithCustomIcon
	setMode: (mode: MenuActionWithCustomIcon) => void
	actions: MenuActionWithCustomIcon[]
}

export const ModeDropdown = ({ mode, setMode, actions }: ModeDropdownProps) => {
	const { theme } = useTheme()

	const menuRef = useRef<MenuComponentRef>(null)

	const cleanActions: MenuAction[] = actions.map(({ ...action }) => ({
		...action,
		state: action.id === mode.id ? 'on' : 'off'
	}))

	const defaultColors: MappedColorsType = {
		borderColor: colors[theme].gray[400]
	}

	const mappedColors: Record<string, MappedColorsType> = {
		discussion: {
			backgroundColor: colors[theme].blue[25],
			borderColor: colors[theme].blue[600]
		},
		fast: {
			backgroundColor: colors[theme].yellow[25],
			borderColor: colors[theme].yellow[800]
		}
	}

	return (
		<MenuView
			ref={menuRef}
			onPressAction={({ nativeEvent }) => {
				const action = actions.find((a) => a.id === nativeEvent.event)
				if (action) {
					setMode(action)
				}
			}}
			actions={cleanActions}
		>
			<View
				style={[
					styles.dropdownButton(theme),
					mode.id && {
						backgroundColor:
							mappedColors[mode.id]?.backgroundColor ??
							defaultColors.backgroundColor,
						borderColor:
							mappedColors[mode.id]?.borderColor ?? defaultColors.borderColor
					}
				]}
			>
				<Text
					style={[
						styles.dropdownButtonText(theme),
						{
							color:
								(mode.id && mappedColors[mode.id]?.borderColor) ||
								defaultColors.borderColor
						}
					]}
				>
					{mode.title}
				</Text>
				<ChevronRight
					size={20}
					color={
						(mode.id && mappedColors[mode.id]?.borderColor) ||
						defaultColors.borderColor
					}
				/>
			</View>
		</MenuView>
	)
}

const styles = defineStyles({
	dropdownButton: (theme: Theme) => ({
		paddingVertical: 6,
		paddingHorizontal: 8,
		borderWidth: 1,
		borderColor: colors[theme].gray[400],
		borderRadius: 12,
		flexDirection: 'row',
		justifyContent: 'center',
		alignItems: 'center',
		gap: 8
	}),
	dropdownButtonText: (theme: Theme) => ({
		color: colors[theme].gray[400],
		fontSize: 16,
		fontWeight: '500'
	})
})
